def compute(vars):
    labor_claim = vars["v1"]
    total_obligations = vars["v2"]

    if total_obligations == 0:
        return None

    portion = labor_claim / total_obligations
    return {
        "value": portion,
        "trace": {
            "labor_claim": labor_claim,
            "total_obligations": total_obligations,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
